INSERT INTO book (id, content_type, slug, title, description, cover_image_url, published_date, publisher, file_format, page_count, volume_label, publish_cycle, serial_status, publish_status, submitted_by_member_id, view_count, recommend_count, created_at, updated_at) VALUES
    (81001, 'WEBNOVEL', 'novel-record', '괴이청 야간기록관', '사람들이 잠든 뒤에만 문을 여는 괴이청에서 신입 기록관이 첫 야간 근무를 시작합니다. 기록에서 지워진 사건을 따라가며 도시의 평범한 풍경 뒤에 숨은 기이한 규칙을 밝혀갑니다.', CONCAT(@mobtwig_asset_origin, '/media/covers/웹소설/괴이청 야간기록관.png'), '2026-09-12', '모북이 스토리', 'TEXT', NULL, NULL, '화·목·토 연재', 'ONGOING', 'PUBLISHED', NULL, 12000, 486, TIMESTAMP('2026-09-12'), DATE_SUB(v_now, INTERVAL 0 HOUR)),
    (81002, 'BOOK', 'book-care', '나를 돌보는 연습', '자신의 마음을 살피는 일을 작은 일상의 습관에서 시작하도록 돕는 에세이입니다. 감정을 기록하고 휴식을 선택하는 순간들을 통해 오늘의 자신에게 필요한 돌봄을 찾아갑니다.', CONCAT(@mobtwig_asset_origin, '/media/covers/도서/나를 돌보는 연습.png'), '2026-09-18', '모북출판', 'EPUB', 248, NULL, NULL, 'COMPLETED', 'PUBLISHED', NULL, 8460, 0, TIMESTAMP('2026-09-18'), DATE_SUB(v_now, INTERVAL 0 HOUR)),
    (81003, 'BOOK', 'book-slow', '느리게 사는 기술', '해야 할 일을 늘리기보다 하루의 여백을 만드는 방법을 소개합니다. 식사와 산책, 관계와 일의 속도를 돌아보며 자신에게 맞는 생활 리듬을 찾는 과정을 담았습니다.', CONCAT(@mobtwig_asset_origin, '/media/covers/도서/느리게 사는 기술.png'), '2026-07-30', '작은걸음', 'EPUB', 232, NULL, NULL, 'COMPLETED', 'PUBLISHED', NULL, 5230, 0, TIMESTAMP('2026-07-30'), DATE_SUB(v_now, INTERVAL 0 HOUR)),
    (81004, 'MAGAZINE', 'magazine-orbit', 'ORBIT 월간 과학', '우주와 일상에서 발견하는 과학의 질문을 함께 살펴봅니다. 이번 호에서는 밤하늘을 관측하는 사람들의 기록과 탐사 장비, 빛을 통해 세상을 이해하는 방법을 소개합니다.', CONCAT(@mobtwig_asset_origin, '/media/covers/매거진/ORBIT 월간 과학.png'), '2026-10-01', '모북이 사이언스', 'APPBOOK', 92, '2026.10 · VOL.08', '월간', 'COMPLETED', 'PUBLISHED', NULL, 18620, 0, TIMESTAMP('2026-10-01'), DATE_SUB(v_now, INTERVAL 0 HOUR)),
    (81005, 'MAGAZINE', 'magazine-room', 'ROOM 공간과 생활', '사는 사람의 취향과 생활이 담긴 공간을 만나는 매거진입니다. 이번 호에서는 작은 집의 수납, 빛이 드는 작업실, 이웃과 나누는 공용 공간을 둘러봅니다.', CONCAT(@mobtwig_asset_origin, '/media/covers/매거진/ROOM 공간과 생활.png'), '2026-10-01', '모북이 리빙', 'APPBOOK', 112, '2026.10 · VOL.12', '월간', 'COMPLETED', 'PUBLISHED', NULL, 9340, 0, TIMESTAMP('2026-10-01'), DATE_SUB(v_now, INTERVAL 0 HOUR)),
    (81006, 'BOOK', 'book-cloud', '구름섬 우체부', '하늘 위 작은 섬에서 길을 잃은 편지를 배달하는 우체부의 여정을 그립니다. 수신인이 지워진 편지 한 통을 따라가며 잊힌 약속과 서로를 기다리는 마음을 만납니다.', CONCAT(@mobtwig_asset_origin, '/media/covers/도서/구름섬 우체부.png'), '2026-08-21', '구름숲', 'EPUB', 304, NULL, NULL, 'COMPLETED', 'PUBLISHED', NULL, 12480, 0, TIMESTAMP('2026-08-21'), DATE_SUB(v_now, INTERVAL 0 HOUR)),
    (81007, 'BOOK', 'book-react-native', 'React Native 첫걸음', '작은 모바일 화면을 만들며 React Native의 기본 개념을 익히는 입문서입니다. 컴포넌트와 상태, 화면 이동과 서버 연결을 차례로 살펴보는 학습 흐름으로 구성했습니다.', CONCAT(@mobtwig_asset_origin, '/media/covers/도서/React Native 첫걸음.png'), '2026-10-05', '모북테크', 'EPUB', 368, NULL, NULL, 'COMPLETED', 'PUBLISHED', NULL, 6500, 0, TIMESTAMP('2026-10-05'), DATE_SUB(v_now, INTERVAL 0 HOUR)),
    (81008, 'WEBNOVEL', 'novel-princess', '황녀는 결말을 바꾼다', '자신의 비극적인 결말을 읽어 버린 황녀가 정해진 운명에서 벗어나기로 결심합니다. 오래된 동맹과 낯선 선택 사이에서 스스로의 이야기를 만들어 가는 로맨스 판타지입니다.', CONCAT(@mobtwig_asset_origin, '/media/covers/웹소설/황녀는 결말을 바꾼다.png'), '2026-08-28', '모북이 스토리', 'TEXT', NULL, NULL, '화·목·토 연재', 'ONGOING', 'PUBLISHED', NULL, 98000, 2468, TIMESTAMP('2026-08-28'), DATE_SUB(v_now, INTERVAL 0 HOUR)),
    (81009, 'BOOK', 'book-quiet', '고요를 연습하는 시간', '분주한 하루 속에서 자신만의 속도를 되찾는 방법을 이야기합니다. 창가에 앉는 짧은 시간, 아무 말 없이 걷는 저녁처럼 일상에서 시도할 수 있는 고요의 순간을 담았습니다.', CONCAT(@mobtwig_asset_origin, '/media/covers/도서/고요를 연습하는 시간.png'), '2026-09-03', '모북출판', 'EPUB', 216, NULL, NULL, 'COMPLETED', 'PUBLISHED', NULL, 4820, 0, TIMESTAMP('2026-09-03'), DATE_SUB(v_now, INTERVAL 0 HOUR)),
    (81010, 'BOOK', 'book-thoughts', '생각을 정리하는 작은 습관', '머릿속에 흩어진 생각을 짧은 메모와 질문으로 정리하는 연습을 제안합니다. 하루를 돌아보는 기록부터 선택의 기준을 세우는 목록까지 부담 없이 시작할 수 있는 예시를 담았습니다.', CONCAT(@mobtwig_asset_origin, '/media/covers/도서/생각을 정리하는 작은 습관.png'), '2026-09-09', '생각의칸', 'EPUB', 192, NULL, NULL, 'COMPLETED', 'PUBLISHED', NULL, 6190, 0, TIMESTAMP('2026-09-09'), DATE_SUB(v_now, INTERVAL 0 HOUR)),
    (81011, 'MAGAZINE', 'magazine-paper', 'PAPER 문학의 계절', '계절의 변화와 함께 읽을 소설, 시, 에세이를 소개하는 문학 매거진입니다. 이번 호는 오래 간직한 문장과 새로운 시작을 주제로 작가들의 짧은 글과 대화를 엮었습니다.', CONCAT(@mobtwig_asset_origin, '/media/covers/매거진/PAPER 문학의 계절.png'), '2026-10-01', '모북이 문학', 'APPBOOK', 128, '2026.10 · VOL.21', '월간', 'COMPLETED', 'PUBLISHED', NULL, 7820, 0, TIMESTAMP('2026-10-01'), DATE_SUB(v_now, INTERVAL 0 HOUR)),
    (81012, 'MAGAZINE', 'magazine-table', 'TABLE 일상의 식탁', '재료를 고르고 한 끼를 차리는 일상의 이야기를 전합니다. 이번 호에서는 가을 채소로 만드는 식탁과 작은 가게의 조리 기록, 함께 먹는 시간을 소개합니다.', CONCAT(@mobtwig_asset_origin, '/media/covers/매거진/TABLE 일상의 식탁.png'), '2026-10-01', '모북이 푸드', 'APPBOOK', 96, '2026.10 · VOL.17', '월간', 'COMPLETED', 'PUBLISHED', NULL, 11240, 0, TIMESTAMP('2026-10-01'), DATE_SUB(v_now, INTERVAL 0 HOUR)),
    (81013, 'MAGAZINE', 'magazine-frame', 'FRAME 디자인 저널', '일상 속 디자인이 만들어지는 과정을 살펴보는 매거진입니다. 이번 호에서는 작은 브랜드의 시각 언어, 오래 쓰는 물건, 도시의 안내 체계를 만드는 사람들을 소개합니다.', CONCAT(@mobtwig_asset_origin, '/media/covers/매거진/FRAME 디자인 저널.png'), '2026-10-01', '모북이 디자인', 'APPBOOK', 104, '2026.10 · VOL.32', '월간', 'COMPLETED', 'PUBLISHED', NULL, 9630, 0, TIMESTAMP('2026-10-01'), DATE_SUB(v_now, INTERVAL 0 HOUR)),
    (81014, 'WEBNOVEL', 'novel-dungeon', '퇴근 후 던전 관리인', '평범한 회사원이 퇴근길에 낡은 던전의 관리 계약을 맺게 됩니다. 낮에는 업무를, 밤에는 몬스터와 시설을 관리하며 두 일상 사이에서 뜻밖의 동료를 만납니다.', CONCAT(@mobtwig_asset_origin, '/media/covers/웹소설/퇴근 후 던전 관리인.png'), '2026-09-02', '모북이 스토리', 'TEXT', NULL, NULL, '월·수·금 연재', 'ONGOING', 'PUBLISHED', 81001, 246000, 8132, TIMESTAMP('2026-09-02'), DATE_SUB(v_now, INTERVAL 0 HOUR)),
    (81015, 'WEBNOVEL', 'novel-marriage', '계약 결혼의 마지막 페이지', '서로의 비밀을 지키기 위해 시작한 계약 결혼에 정해진 마지막 날이 다가옵니다. 계약서에 쓰지 못한 마음을 마주한 두 사람이 자신들의 결말을 다시 선택하는 로맨스 이야기입니다.', CONCAT(@mobtwig_asset_origin, '/media/covers/웹소설/계약 결혼의 마지막 페이지.png'), '2026-08-05', '모북이 스토리', 'TEXT', NULL, NULL, '월·수·금 연재', 'ONGOING', 'PUBLISHED', NULL, 182000, 6427, TIMESTAMP('2026-08-05'), DATE_SUB(v_now, INTERVAL 0 HOUR)),
    (81016, 'WEBNOVEL', 'novel-library', '멸망한 세계의 도서관', '모든 도시가 무너진 뒤에도 한 도서관의 불빛만은 꺼지지 않습니다. 마지막 사서가 책 속에 남은 기억을 모으며 세상을 다시 잇는 길을 찾는 판타지 이야기입니다.', CONCAT(@mobtwig_asset_origin, '/media/covers/웹소설/멸망한 세계의 도서관.png'), '2026-07-17', '모북이 스토리', 'TEXT', NULL, NULL, '월·화·목·금 연재', 'ONGOING', 'PUBLISHED', NULL, 321000, 12000, TIMESTAMP('2026-07-17'), DATE_SUB(v_now, INTERVAL 0 HOUR));
