INSERT INTO bookmark (id, member_id, book_id, chapter_id, chapter_offset, snippet, content_version, created_at) VALUES
    (81001, 81001, 81001, 81001002, 320, '막차가 떠나자 승강장의 시계가 자정에 멈췄다.', 1, DATE_SUB(v_now, INTERVAL 2 HOUR)),
    (81002, 81001, 81002, 81002002, 1800, '감정에 이름을 붙이고 나면 필요한 것이 조금 더 선명해진다.', 1, DATE_SUB(v_now, INTERVAL 24 HOUR)),
    (81003, 81001, 81004, 81004003, 35, '토성의 고리를 관측할 때 알아둘 점', 1, DATE_SUB(v_now, INTERVAL 48 HOUR)),
    (81004, 81001, 81014, 81014034, 640, '관리실 책상 위에 두 번째 민원 봉투가 놓여 있었다.', 1, DATE_SUB(v_now, INTERVAL 72 HOUR));
INSERT INTO highlight (id, member_id, book_id, chapter_id, start_offset, end_offset, snippet, content_version, color, memo, created_at, updated_at) VALUES
    (81001, 81001, 81001, 81001002, 700, 728, '기록되지 않은 밤을 끝까지 기억하는 사람이 있었다.', 1, 'YELLOW', '기록관이 하는 일을 잘 보여 주는 문장입니다.', DATE_SUB(v_now, INTERVAL 3 HOUR), DATE_SUB(v_now, INTERVAL 3 HOUR)),
    (81002, 81001, 81002, 81002001, 250, 281, '오늘은 무엇을 했는지보다 어떤 마음이었는지 먼저 묻는다.', 1, 'GREEN', '일기를 쓸 때 이 질문으로 시작해 보고 싶습니다.', DATE_SUB(v_now, INTERVAL 24 HOUR), DATE_SUB(v_now, INTERVAL 24 HOUR)),
    (81003, 81001, 81009, 81009001, 400, 429, '아무것도 하지 않는 시간에도 마음은 조금씩 정리된다.', 1, 'YELLOW', NULL, DATE_SUB(v_now, INTERVAL 96 HOUR), DATE_SUB(v_now, INTERVAL 96 HOUR)),
    (81004, 81001, 81010, 81010002, 900, 929, '기억하려 애쓰기보다 다시 찾을 수 있는 곳에 적는다.', 1, 'GREEN', '메모 앱을 하나로 정리하기로 했습니다.', DATE_SUB(v_now, INTERVAL 120 HOUR), DATE_SUB(v_now, INTERVAL 120 HOUR));
INSERT INTO review (id, book_id, member_id, rating, content, created_at, updated_at) VALUES
    (810101, 81001, 81002, 5, '폐역 장면에서 분위기가 확 살아나네요. 괴이가 갑자기 튀어나오는 것보다 근무 규칙이 하나씩 이상해지는 쪽이라 더 긴장하면서 읽었습니다. 윤서가 매번 기록부터 챙기는 것도 좋았어요.', DATE_SUB(v_now, INTERVAL 72 HOUR), DATE_SUB(v_now, INTERVAL 72 HOUR)),
    (810102, 81001, 81003, 5, '야간 근무 끝나고 읽다가 정류장 하나 지나쳤습니다. 사건이 끝난 뒤 기록실에서 대화하는 장면까지 재미있어서 다음 화를 바로 눌렀어요.', DATE_SUB(v_now, INTERVAL 96 HOUR), DATE_SUB(v_now, INTERVAL 96 HOUR)),
    (810103, 81001, 81004, 5, NULL, DATE_SUB(v_now, INTERVAL 120 HOUR), DATE_SUB(v_now, INTERVAL 120 HOUR)),
    (810104, 81001, 81005, 5, NULL, DATE_SUB(v_now, INTERVAL 144 HOUR), DATE_SUB(v_now, INTERVAL 144 HOUR)),
    (810105, 81001, 81006, 5, NULL, DATE_SUB(v_now, INTERVAL 168 HOUR), DATE_SUB(v_now, INTERVAL 168 HOUR)),
    (810106, 81001, 81007, 5, NULL, DATE_SUB(v_now, INTERVAL 192 HOUR), DATE_SUB(v_now, INTERVAL 192 HOUR)),
    (810107, 81001, 81008, 5, NULL, DATE_SUB(v_now, INTERVAL 216 HOUR), DATE_SUB(v_now, INTERVAL 216 HOUR)),
    (810108, 81001, 81009, 5, NULL, DATE_SUB(v_now, INTERVAL 240 HOUR), DATE_SUB(v_now, INTERVAL 240 HOUR)),
    (810109, 81001, 81010, 4, NULL, DATE_SUB(v_now, INTERVAL 264 HOUR), DATE_SUB(v_now, INTERVAL 264 HOUR)),
    (810110, 81001, 81011, 4, '설정은 재미있는데 초반에 고유명사가 연달아 나와서 한 번 되돌아갔어요. 세계관 용어를 같이 보니 훨씬 편하게 읽혔습니다.', DATE_SUB(v_now, INTERVAL 288 HOUR), DATE_SUB(v_now, INTERVAL 288 HOUR)),
    (810201, 81002, 81002, 5, '막연히 쉬라는 얘기만 할 줄 알았는데 하루를 돌아보는 질문이 구체적이라 좋았습니다. 감정에 이름 붙이는 부분은 메모하면서 읽었어요. 한 번에 읽기보다 자기 전에 조금씩 보는 편이 맞네요.', DATE_SUB(v_now, INTERVAL 72 HOUR), DATE_SUB(v_now, INTERVAL 72 HOUR)),
    (810202, 81002, 81003, 5, '계속 괜찮다고 넘기던 마음을 돌아보게 됐어요. 문장이 길지 않아서 출근길에 한 장씩 읽기 좋았습니다.', DATE_SUB(v_now, INTERVAL 96 HOUR), DATE_SUB(v_now, INTERVAL 96 HOUR)),
    (810203, 81002, 81004, 5, NULL, DATE_SUB(v_now, INTERVAL 120 HOUR), DATE_SUB(v_now, INTERVAL 120 HOUR)),
    (810204, 81002, 81005, 5, NULL, DATE_SUB(v_now, INTERVAL 144 HOUR), DATE_SUB(v_now, INTERVAL 144 HOUR)),
    (810205, 81002, 81006, 5, NULL, DATE_SUB(v_now, INTERVAL 168 HOUR), DATE_SUB(v_now, INTERVAL 168 HOUR)),
    (810206, 81002, 81007, 5, NULL, DATE_SUB(v_now, INTERVAL 192 HOUR), DATE_SUB(v_now, INTERVAL 192 HOUR)),
    (810207, 81002, 81008, 5, NULL, DATE_SUB(v_now, INTERVAL 216 HOUR), DATE_SUB(v_now, INTERVAL 216 HOUR)),
    (810208, 81002, 81009, 5, NULL, DATE_SUB(v_now, INTERVAL 240 HOUR), DATE_SUB(v_now, INTERVAL 240 HOUR)),
    (810209, 81002, 81010, 4, NULL, DATE_SUB(v_now, INTERVAL 264 HOUR), DATE_SUB(v_now, INTERVAL 264 HOUR)),
    (810210, 81002, 81011, 4, '앞부분은 많이 공감했는데 뒤로 갈수록 비슷한 이야기가 조금 반복됩니다. 그래도 나에게 약속을 작게 잡으라는 부분은 바로 해봤어요.', DATE_SUB(v_now, INTERVAL 288 HOUR), DATE_SUB(v_now, INTERVAL 288 HOUR)),
    (810301, 81003, 81002, 5, '하루 계획에서 한 가지를 빼보라는 이야기가 기억에 남습니다. 시간을 더 채우는 방법이 아니라 비우는 쪽이라 부담 없이 읽었어요.', DATE_SUB(v_now, INTERVAL 72 HOUR), DATE_SUB(v_now, INTERVAL 72 HOUR)),
    (810302, 81003, 81003, 5, '잠깐 산책하는 시간을 먼저 잡아두기 시작했습니다. 거창한 방법보다 생활에서 해볼 만한 제안이 많아서 좋았어요.', DATE_SUB(v_now, INTERVAL 96 HOUR), DATE_SUB(v_now, INTERVAL 96 HOUR)),
    (810303, 81003, 81004, 5, NULL, DATE_SUB(v_now, INTERVAL 120 HOUR), DATE_SUB(v_now, INTERVAL 120 HOUR)),
    (810304, 81003, 81005, 5, NULL, DATE_SUB(v_now, INTERVAL 144 HOUR), DATE_SUB(v_now, INTERVAL 144 HOUR)),
    (810305, 81003, 81006, 5, NULL, DATE_SUB(v_now, INTERVAL 168 HOUR), DATE_SUB(v_now, INTERVAL 168 HOUR)),
    (810306, 81003, 81007, 5, NULL, DATE_SUB(v_now, INTERVAL 192 HOUR), DATE_SUB(v_now, INTERVAL 192 HOUR)),
    (810307, 81003, 81008, 5, NULL, DATE_SUB(v_now, INTERVAL 216 HOUR), DATE_SUB(v_now, INTERVAL 216 HOUR)),
    (810308, 81003, 81009, 4, NULL, DATE_SUB(v_now, INTERVAL 240 HOUR), DATE_SUB(v_now, INTERVAL 240 HOUR)),
    (810309, 81003, 81010, 4, NULL, DATE_SUB(v_now, INTERVAL 264 HOUR), DATE_SUB(v_now, INTERVAL 264 HOUR)),
    (810310, 81003, 81011, 4, '익숙한 조언도 꽤 있지만 사례가 짧아서 읽기 편합니다. 중간중간 필요한 부분만 다시 찾아보고 있어요.', DATE_SUB(v_now, INTERVAL 288 HOUR), DATE_SUB(v_now, INTERVAL 288 HOUR)),
    (810401, 81004, 81002, 5, '목성 찾는 순서가 그림과 함께 정리돼 있어서 망원경 없이도 따라가 볼 만했어요. 관측 캘린더는 따로 책갈피해뒀습니다.', DATE_SUB(v_now, INTERVAL 72 HOUR), DATE_SUB(v_now, INTERVAL 72 HOUR)),
    (810402, 81004, 81003, 5, '사진만 보려고 열었다가 토성의 고리 기사까지 다 읽었네요. 용어 설명이 바로 붙어 있어서 과학을 오래 안 읽은 사람도 괜찮았습니다.', DATE_SUB(v_now, INTERVAL 96 HOUR), DATE_SUB(v_now, INTERVAL 96 HOUR)),
    (810403, 81004, 81004, 5, NULL, DATE_SUB(v_now, INTERVAL 120 HOUR), DATE_SUB(v_now, INTERVAL 120 HOUR)),
    (810404, 81004, 81005, 5, NULL, DATE_SUB(v_now, INTERVAL 144 HOUR), DATE_SUB(v_now, INTERVAL 144 HOUR)),
    (810405, 81004, 81006, 5, NULL, DATE_SUB(v_now, INTERVAL 168 HOUR), DATE_SUB(v_now, INTERVAL 168 HOUR)),
    (810406, 81004, 81007, 5, NULL, DATE_SUB(v_now, INTERVAL 192 HOUR), DATE_SUB(v_now, INTERVAL 192 HOUR)),
    (810407, 81004, 81008, 5, NULL, DATE_SUB(v_now, INTERVAL 216 HOUR), DATE_SUB(v_now, INTERVAL 216 HOUR)),
    (810408, 81004, 81009, 5, NULL, DATE_SUB(v_now, INTERVAL 240 HOUR), DATE_SUB(v_now, INTERVAL 240 HOUR)),
    (810409, 81004, 81010, 4, NULL, DATE_SUB(v_now, INTERVAL 264 HOUR), DATE_SUB(v_now, INTERVAL 264 HOUR)),
    (810410, 81004, 81011, 4, '사진은 좋은데 휴대폰에서는 도표 안의 글씨가 작네요. 확대해서 읽으면 되지만 표는 한 번에 비교하기 어려웠어요.', DATE_SUB(v_now, INTERVAL 288 HOUR), DATE_SUB(v_now, INTERVAL 288 HOUR)),
    (810501, 81005, 81002, 5, '열두 평 집 소개가 가장 좋았습니다. 사진만 예쁜 게 아니라 수납을 어떻게 바꿨는지 설명이 있어서 우리 집에도 대입해봤어요.', DATE_SUB(v_now, INTERVAL 72 HOUR), DATE_SUB(v_now, INTERVAL 72 HOUR)),
    (810502, 81005, 81003, 5, '작업실마다 빛이 들어오는 시간이 다른 게 재미있어요. 같은 공간을 오전과 오후로 나눠 보여준 구성이 좋았습니다.', DATE_SUB(v_now, INTERVAL 96 HOUR), DATE_SUB(v_now, INTERVAL 96 HOUR)),
    (810503, 81005, 81004, 5, NULL, DATE_SUB(v_now, INTERVAL 120 HOUR), DATE_SUB(v_now, INTERVAL 120 HOUR)),
    (810504, 81005, 81005, 5, NULL, DATE_SUB(v_now, INTERVAL 144 HOUR), DATE_SUB(v_now, INTERVAL 144 HOUR)),
    (810505, 81005, 81006, 5, NULL, DATE_SUB(v_now, INTERVAL 168 HOUR), DATE_SUB(v_now, INTERVAL 168 HOUR)),
    (810506, 81005, 81007, 5, NULL, DATE_SUB(v_now, INTERVAL 192 HOUR), DATE_SUB(v_now, INTERVAL 192 HOUR)),
    (810507, 81005, 81008, 4, NULL, DATE_SUB(v_now, INTERVAL 216 HOUR), DATE_SUB(v_now, INTERVAL 216 HOUR)),
    (810508, 81005, 81009, 4, NULL, DATE_SUB(v_now, INTERVAL 240 HOUR), DATE_SUB(v_now, INTERVAL 240 HOUR)),
    (810509, 81005, 81010, 4, NULL, DATE_SUB(v_now, INTERVAL 264 HOUR), DATE_SUB(v_now, INTERVAL 264 HOUR)),
    (810510, 81005, 81011, 4, '소개한 물건 중 가격대가 높은 편이라 그대로 따라 하기는 어렵습니다. 공간을 나누는 아이디어 위주로 읽었어요.', DATE_SUB(v_now, INTERVAL 288 HOUR), DATE_SUB(v_now, INTERVAL 288 HOUR)),
    (810601, 81006, 81002, 5, '편지마다 기다리는 사람이 달라서 한 장 더 읽게 됩니다. 조카에게 읽어주려고 골랐는데 제가 먼저 끝까지 봤어요.', DATE_SUB(v_now, INTERVAL 72 HOUR), DATE_SUB(v_now, INTERVAL 72 HOUR)),
    (810602, 81006, 81003, 5, '구름섬 풍경을 떠올리며 읽는 재미가 있어요. 마지막 배달에서 앞의 편지들이 이어지는 부분이 특히 좋았습니다.', DATE_SUB(v_now, INTERVAL 96 HOUR), DATE_SUB(v_now, INTERVAL 96 HOUR)),
    (810603, 81006, 81004, 5, NULL, DATE_SUB(v_now, INTERVAL 120 HOUR), DATE_SUB(v_now, INTERVAL 120 HOUR)),
    (810604, 81006, 81005, 5, NULL, DATE_SUB(v_now, INTERVAL 144 HOUR), DATE_SUB(v_now, INTERVAL 144 HOUR)),
    (810605, 81006, 81006, 5, NULL, DATE_SUB(v_now, INTERVAL 168 HOUR), DATE_SUB(v_now, INTERVAL 168 HOUR)),
    (810606, 81006, 81007, 5, NULL, DATE_SUB(v_now, INTERVAL 192 HOUR), DATE_SUB(v_now, INTERVAL 192 HOUR)),
    (810607, 81006, 81008, 5, NULL, DATE_SUB(v_now, INTERVAL 216 HOUR), DATE_SUB(v_now, INTERVAL 216 HOUR)),
    (810608, 81006, 81009, 5, NULL, DATE_SUB(v_now, INTERVAL 240 HOUR), DATE_SUB(v_now, INTERVAL 240 HOUR)),
    (810609, 81006, 81010, 5, NULL, DATE_SUB(v_now, INTERVAL 264 HOUR), DATE_SUB(v_now, INTERVAL 264 HOUR)),
    (810610, 81006, 81011, 4, '따뜻한 이야기라 편하게 읽었습니다. 중간 여정이 조금 빠르게 지나가서 몇몇 섬은 더 오래 보고 싶었어요.', DATE_SUB(v_now, INTERVAL 288 HOUR), DATE_SUB(v_now, INTERVAL 288 HOUR)),
    (810701, 81007, 81002, 5, '화면 하나를 직접 실행한 다음 컴포넌트를 나누는 순서가 이해하기 편했습니다. 처음 상태를 배울 때 막혔던 부분이 정리됐어요.', DATE_SUB(v_now, INTERVAL 72 HOUR), DATE_SUB(v_now, INTERVAL 72 HOUR)),
    (810702, 81007, 81003, 5, '웹 React 경험이 조금 있는데 모바일 화면 이동과 서버 응답 부분이 도움이 됐습니다. 코드를 따라 쓰는 것보다 역할을 나눠 설명한 부분이 좋았어요.', DATE_SUB(v_now, INTERVAL 96 HOUR), DATE_SUB(v_now, INTERVAL 96 HOUR)),
    (810703, 81007, 81004, 5, NULL, DATE_SUB(v_now, INTERVAL 120 HOUR), DATE_SUB(v_now, INTERVAL 120 HOUR)),
    (810704, 81007, 81005, 5, NULL, DATE_SUB(v_now, INTERVAL 144 HOUR), DATE_SUB(v_now, INTERVAL 144 HOUR)),
    (810705, 81007, 81006, 5, NULL, DATE_SUB(v_now, INTERVAL 168 HOUR), DATE_SUB(v_now, INTERVAL 168 HOUR)),
    (810706, 81007, 81007, 4, NULL, DATE_SUB(v_now, INTERVAL 192 HOUR), DATE_SUB(v_now, INTERVAL 192 HOUR)),
    (810707, 81007, 81008, 4, NULL, DATE_SUB(v_now, INTERVAL 216 HOUR), DATE_SUB(v_now, INTERVAL 216 HOUR)),
    (810708, 81007, 81009, 4, NULL, DATE_SUB(v_now, INTERVAL 240 HOUR), DATE_SUB(v_now, INTERVAL 240 HOUR)),
    (810709, 81007, 81010, 4, NULL, DATE_SUB(v_now, INTERVAL 264 HOUR), DATE_SUB(v_now, INTERVAL 264 HOUR)),
    (810710, 81007, 81011, 4, '입문 흐름은 좋습니다. 다만 개발 환경 버전에 따라 설치 화면이 달라서 공식 문서를 같이 열어두고 따라갔어요.', DATE_SUB(v_now, INTERVAL 288 HOUR), DATE_SUB(v_now, INTERVAL 288 HOUR)),
    (810801, 81008, 81002, 5, '황녀가 결말을 알고 있다고 모든 일이 바로 해결되지는 않아서 좋았어요. 무도회에서 선택을 바꾸는 장면부터 계속 읽게 됐습니다.', DATE_SUB(v_now, INTERVAL 72 HOUR), DATE_SUB(v_now, INTERVAL 72 HOUR)),
    (810802, 81008, 81003, 5, '동맹을 맺는 과정이 설득력 있어요. 로맨스만큼 궁정 사람들 사이의 대화가 재미있어서 다음 회차를 기다리고 있습니다.', DATE_SUB(v_now, INTERVAL 96 HOUR), DATE_SUB(v_now, INTERVAL 96 HOUR)),
    (810803, 81008, 81004, 5, NULL, DATE_SUB(v_now, INTERVAL 120 HOUR), DATE_SUB(v_now, INTERVAL 120 HOUR)),
    (810804, 81008, 81005, 5, NULL, DATE_SUB(v_now, INTERVAL 144 HOUR), DATE_SUB(v_now, INTERVAL 144 HOUR)),
    (810805, 81008, 81006, 5, NULL, DATE_SUB(v_now, INTERVAL 168 HOUR), DATE_SUB(v_now, INTERVAL 168 HOUR)),
    (810806, 81008, 81007, 5, NULL, DATE_SUB(v_now, INTERVAL 192 HOUR), DATE_SUB(v_now, INTERVAL 192 HOUR)),
    (810807, 81008, 81008, 5, NULL, DATE_SUB(v_now, INTERVAL 216 HOUR), DATE_SUB(v_now, INTERVAL 216 HOUR)),
    (810808, 81008, 81009, 5, NULL, DATE_SUB(v_now, INTERVAL 240 HOUR), DATE_SUB(v_now, INTERVAL 240 HOUR)),
    (810809, 81008, 81010, 5, NULL, DATE_SUB(v_now, INTERVAL 264 HOUR), DATE_SUB(v_now, INTERVAL 264 HOUR)),
    (810810, 81008, 81011, 4, '초반 등장인물이 한꺼번에 나와서 이름을 좀 헷갈렸어요. 탑의 편지 이후로는 인물 관계가 잡혀서 편하게 읽었습니다.', DATE_SUB(v_now, INTERVAL 288 HOUR), DATE_SUB(v_now, INTERVAL 288 HOUR)),
    (810901, 81009, 81002, 5, '잠들기 전에 휴대폰을 계속 보게 됐는데 이 책은 두세 쪽만 읽고 덮기 좋네요. 짧은 글 사이에 여백이 있어서 쉬어가는 느낌입니다.', DATE_SUB(v_now, INTERVAL 72 HOUR), DATE_SUB(v_now, INTERVAL 72 HOUR)),
    (810902, 81009, 81003, 5, '평소 지나치던 소리에 귀를 기울이게 됐어요. 아침 장은 주말에 다시 읽고 싶어서 책갈피해뒀습니다.', DATE_SUB(v_now, INTERVAL 96 HOUR), DATE_SUB(v_now, INTERVAL 96 HOUR)),
    (810903, 81009, 81004, 5, NULL, DATE_SUB(v_now, INTERVAL 120 HOUR), DATE_SUB(v_now, INTERVAL 120 HOUR)),
