    (810908, 81009, 81009, 5, NULL, DATE_SUB(v_now, INTERVAL 240 HOUR), DATE_SUB(v_now, INTERVAL 240 HOUR)),
    (810909, 81009, 81010, 4, NULL, DATE_SUB(v_now, INTERVAL 264 HOUR), DATE_SUB(v_now, INTERVAL 264 HOUR)),
    (810910, 81009, 81011, 4, '문장은 편안하지만 한 번에 많이 읽으면 비슷하게 느껴집니다. 하루 한 장 정도가 저한테는 잘 맞았어요.', DATE_SUB(v_now, INTERVAL 288 HOUR), DATE_SUB(v_now, INTERVAL 288 HOUR)),
    (811001, 81010, 81002, 5, '메모를 많이 해도 다시 안 보던 편인데 찾을 수 있게 적으라는 부분이 도움이 됐어요. 할 일과 떠오른 생각을 나누기 시작했습니다.', DATE_SUB(v_now, INTERVAL 72 HOUR), DATE_SUB(v_now, INTERVAL 72 HOUR)),
    (811002, 81010, 81003, 5, '질문을 먼저 적고 생각을 붙이는 방식이 생각보다 편합니다. 업무 회의 전에 한 번 해봤는데 정리가 빨랐어요.', DATE_SUB(v_now, INTERVAL 96 HOUR), DATE_SUB(v_now, INTERVAL 96 HOUR)),
    (811003, 81010, 81004, 5, NULL, DATE_SUB(v_now, INTERVAL 120 HOUR), DATE_SUB(v_now, INTERVAL 120 HOUR)),
    (811004, 81010, 81005, 5, NULL, DATE_SUB(v_now, INTERVAL 144 HOUR), DATE_SUB(v_now, INTERVAL 144 HOUR)),
    (811005, 81010, 81006, 5, NULL, DATE_SUB(v_now, INTERVAL 168 HOUR), DATE_SUB(v_now, INTERVAL 168 HOUR)),
    (811006, 81010, 81007, 5, NULL, DATE_SUB(v_now, INTERVAL 192 HOUR), DATE_SUB(v_now, INTERVAL 192 HOUR)),
    (811007, 81010, 81008, 4, NULL, DATE_SUB(v_now, INTERVAL 216 HOUR), DATE_SUB(v_now, INTERVAL 216 HOUR)),
    (811008, 81010, 81009, 4, NULL, DATE_SUB(v_now, INTERVAL 240 HOUR), DATE_SUB(v_now, INTERVAL 240 HOUR)),
    (811009, 81010, 81010, 4, NULL, DATE_SUB(v_now, INTERVAL 264 HOUR), DATE_SUB(v_now, INTERVAL 264 HOUR)),
    (811010, 81010, 81011, 4, '정리법 자체는 복잡하지 않습니다. 이미 기록 습관이 있다면 새롭기보다는 기본을 점검하는 용도로 읽기 좋겠어요.', DATE_SUB(v_now, INTERVAL 288 HOUR), DATE_SUB(v_now, INTERVAL 288 HOUR)),
    (811101, 81011, 81002, 5, '단편을 읽고 뒤에 있는 작가 인터뷰를 바로 볼 수 있어서 좋았어요. 첫 문장 이야기를 듣고 나니 소설 앞부분을 다시 펼치게 됩니다.', DATE_SUB(v_now, INTERVAL 72 HOUR), DATE_SUB(v_now, INTERVAL 72 HOUR)),
    (811102, 81011, 81003, 5, '시와 짧은 글이 섞여 있어서 출퇴근길에 끊어 읽기 좋습니다. 추천한 책도 몇 권 찜해뒀어요.', DATE_SUB(v_now, INTERVAL 96 HOUR), DATE_SUB(v_now, INTERVAL 96 HOUR)),
    (811103, 81011, 81004, 5, NULL, DATE_SUB(v_now, INTERVAL 120 HOUR), DATE_SUB(v_now, INTERVAL 120 HOUR)),
    (811104, 81011, 81005, 5, NULL, DATE_SUB(v_now, INTERVAL 144 HOUR), DATE_SUB(v_now, INTERVAL 144 HOUR)),
    (811105, 81011, 81006, 5, NULL, DATE_SUB(v_now, INTERVAL 168 HOUR), DATE_SUB(v_now, INTERVAL 168 HOUR)),
    (811106, 81011, 81007, 5, NULL, DATE_SUB(v_now, INTERVAL 192 HOUR), DATE_SUB(v_now, INTERVAL 192 HOUR)),
    (811107, 81011, 81008, 5, NULL, DATE_SUB(v_now, INTERVAL 216 HOUR), DATE_SUB(v_now, INTERVAL 216 HOUR)),
    (811108, 81011, 81009, 4, NULL, DATE_SUB(v_now, INTERVAL 240 HOUR), DATE_SUB(v_now, INTERVAL 240 HOUR)),
    (811109, 81011, 81010, 4, NULL, DATE_SUB(v_now, INTERVAL 264 HOUR), DATE_SUB(v_now, INTERVAL 264 HOUR)),
    (811110, 81011, 81011, 4, '작가 인터뷰가 조금 더 길었으면 좋겠습니다. 다른 글들도 좋지만 이번 호는 대화 부분이 가장 궁금했어요.', DATE_SUB(v_now, INTERVAL 288 HOUR), DATE_SUB(v_now, INTERVAL 288 HOUR)),
    (811201, 81012, 81002, 5, '남은 채소로 저녁을 만드는 기사가 실용적이었어요. 따로 사야 하는 재료가 많지 않아서 바로 따라 해봤습니다.', DATE_SUB(v_now, INTERVAL 72 HOUR), DATE_SUB(v_now, INTERVAL 72 HOUR)),
    (811202, 81012, 81003, 5, '가게 이야기를 읽고 나면 평범한 한 끼도 다르게 보이네요. 음식 사진 색감도 차분해서 오래 보기 좋았습니다.', DATE_SUB(v_now, INTERVAL 96 HOUR), DATE_SUB(v_now, INTERVAL 96 HOUR)),
    (811203, 81012, 81004, 5, NULL, DATE_SUB(v_now, INTERVAL 120 HOUR), DATE_SUB(v_now, INTERVAL 120 HOUR)),
    (811204, 81012, 81005, 5, NULL, DATE_SUB(v_now, INTERVAL 144 HOUR), DATE_SUB(v_now, INTERVAL 144 HOUR)),
    (811205, 81012, 81006, 5, NULL, DATE_SUB(v_now, INTERVAL 168 HOUR), DATE_SUB(v_now, INTERVAL 168 HOUR)),
    (811206, 81012, 81007, 5, NULL, DATE_SUB(v_now, INTERVAL 192 HOUR), DATE_SUB(v_now, INTERVAL 192 HOUR)),
    (811207, 81012, 81008, 5, NULL, DATE_SUB(v_now, INTERVAL 216 HOUR), DATE_SUB(v_now, INTERVAL 216 HOUR)),
    (811208, 81012, 81009, 5, NULL, DATE_SUB(v_now, INTERVAL 240 HOUR), DATE_SUB(v_now, INTERVAL 240 HOUR)),
    (811209, 81012, 81010, 4, NULL, DATE_SUB(v_now, INTERVAL 264 HOUR), DATE_SUB(v_now, INTERVAL 264 HOUR)),
    (811210, 81012, 81011, 4, '레시피는 이해하기 쉬운데 1인분 기준도 함께 있었으면 좋겠어요. 양을 줄여서 만드는 데 조금 계산이 필요했습니다.', DATE_SUB(v_now, INTERVAL 288 HOUR), DATE_SUB(v_now, INTERVAL 288 HOUR)),
    (811301, 81013, 81002, 5, '도시 안내 체계 특집이 좋았습니다. 평소 당연하게 보던 표지판의 크기와 간격을 왜 그렇게 정했는지 알 수 있었어요.', DATE_SUB(v_now, INTERVAL 72 HOUR), DATE_SUB(v_now, INTERVAL 72 HOUR)),
    (811302, 81013, 81003, 5, '완성된 결과뿐 아니라 바뀌기 전 시안도 보여줘서 흥미로웠습니다. 작은 브랜드 인터뷰를 특히 재미있게 읽었어요.', DATE_SUB(v_now, INTERVAL 96 HOUR), DATE_SUB(v_now, INTERVAL 96 HOUR)),
    (811303, 81013, 81004, 5, NULL, DATE_SUB(v_now, INTERVAL 120 HOUR), DATE_SUB(v_now, INTERVAL 120 HOUR)),
    (811304, 81013, 81005, 5, NULL, DATE_SUB(v_now, INTERVAL 144 HOUR), DATE_SUB(v_now, INTERVAL 144 HOUR)),
    (811305, 81013, 81006, 5, NULL, DATE_SUB(v_now, INTERVAL 168 HOUR), DATE_SUB(v_now, INTERVAL 168 HOUR)),
    (811306, 81013, 81007, 5, NULL, DATE_SUB(v_now, INTERVAL 192 HOUR), DATE_SUB(v_now, INTERVAL 192 HOUR)),
    (811307, 81013, 81008, 4, NULL, DATE_SUB(v_now, INTERVAL 216 HOUR), DATE_SUB(v_now, INTERVAL 216 HOUR)),
    (811308, 81013, 81009, 4, NULL, DATE_SUB(v_now, INTERVAL 240 HOUR), DATE_SUB(v_now, INTERVAL 240 HOUR)),
    (811309, 81013, 81010, 4, NULL, DATE_SUB(v_now, INTERVAL 264 HOUR), DATE_SUB(v_now, INTERVAL 264 HOUR)),
    (811310, 81013, 81011, 4, '사진 설명이 간결한 건 좋은데 제작 과정은 조금 더 자세했으면 합니다. 인터뷰에서 다룬 도구도 궁금했어요.', DATE_SUB(v_now, INTERVAL 288 HOUR), DATE_SUB(v_now, INTERVAL 288 HOUR)),
    (811401, 81014, 81002, 5, '몬스터보다 관리비가 무섭다는 설정부터 웃겼어요. 시설 점검이 실제 회사 일처럼 구체적이라 퇴근하고 읽기 좋습니다.', DATE_SUB(v_now, INTERVAL 72 HOUR), DATE_SUB(v_now, INTERVAL 72 HOUR)),
    (811402, 81014, 81003, 5, '슬라임 근무표 나오는 부분에서 웃었습니다. 가벼운 이야기인 줄 알았는데 입주자들이 하나씩 사연을 갖고 있어서 계속 보게 되네요.', DATE_SUB(v_now, INTERVAL 96 HOUR), DATE_SUB(v_now, INTERVAL 96 HOUR)),
    (811403, 81014, 81004, 5, NULL, DATE_SUB(v_now, INTERVAL 120 HOUR), DATE_SUB(v_now, INTERVAL 120 HOUR)),
    (811404, 81014, 81005, 5, NULL, DATE_SUB(v_now, INTERVAL 144 HOUR), DATE_SUB(v_now, INTERVAL 144 HOUR)),
    (811405, 81014, 81006, 5, NULL, DATE_SUB(v_now, INTERVAL 168 HOUR), DATE_SUB(v_now, INTERVAL 168 HOUR)),
    (811406, 81014, 81007, 5, NULL, DATE_SUB(v_now, INTERVAL 192 HOUR), DATE_SUB(v_now, INTERVAL 192 HOUR)),
    (811407, 81014, 81008, 5, NULL, DATE_SUB(v_now, INTERVAL 216 HOUR), DATE_SUB(v_now, INTERVAL 216 HOUR)),
    (811408, 81014, 81009, 5, NULL, DATE_SUB(v_now, INTERVAL 240 HOUR), DATE_SUB(v_now, INTERVAL 240 HOUR)),
    (811409, 81014, 81010, 5, NULL, DATE_SUB(v_now, INTERVAL 264 HOUR), DATE_SUB(v_now, INTERVAL 264 HOUR)),
    (811410, 81014, 81011, 4, '던전 운영 이야기는 재미있는데 회사 장면이 조금 길게 느껴질 때가 있어요. 두 생활이 연결될 때는 확실히 몰입됩니다.', DATE_SUB(v_now, INTERVAL 288 HOUR), DATE_SUB(v_now, INTERVAL 288 HOUR)),
    (811501, 81015, 81002, 5, '계약을 핑계로 서로 선을 지키려는 대화가 좋습니다. 처음 같이 저녁 먹는 장면에서 말과 행동이 다른 게 보여서 웃으면서 읽었어요.', DATE_SUB(v_now, INTERVAL 72 HOUR), DATE_SUB(v_now, INTERVAL 72 HOUR)),
    (811502, 81015, 81003, 5, '오해가 생겨도 대화를 아예 피하지 않아서 편하게 읽었습니다. 계약 만료일이 가까워질수록 작은 행동이 달라지는 게 좋네요.', DATE_SUB(v_now, INTERVAL 96 HOUR), DATE_SUB(v_now, INTERVAL 96 HOUR)),
    (811503, 81015, 81004, 5, NULL, DATE_SUB(v_now, INTERVAL 120 HOUR), DATE_SUB(v_now, INTERVAL 120 HOUR)),
    (811504, 81015, 81005, 5, NULL, DATE_SUB(v_now, INTERVAL 144 HOUR), DATE_SUB(v_now, INTERVAL 144 HOUR)),
    (811505, 81015, 81006, 5, NULL, DATE_SUB(v_now, INTERVAL 168 HOUR), DATE_SUB(v_now, INTERVAL 168 HOUR)),
    (811506, 81015, 81007, 5, NULL, DATE_SUB(v_now, INTERVAL 192 HOUR), DATE_SUB(v_now, INTERVAL 192 HOUR)),
    (811507, 81015, 81008, 5, NULL, DATE_SUB(v_now, INTERVAL 216 HOUR), DATE_SUB(v_now, INTERVAL 216 HOUR)),
    (811508, 81015, 81009, 5, NULL, DATE_SUB(v_now, INTERVAL 240 HOUR), DATE_SUB(v_now, INTERVAL 240 HOUR)),
    (811509, 81015, 81010, 4, NULL, DATE_SUB(v_now, INTERVAL 264 HOUR), DATE_SUB(v_now, INTERVAL 264 HOUR)),
    (811510, 81015, 81011, 4, '초반 관계 설명이 약간 길지만 같은 집에서 지내기 시작한 뒤로 재미있어집니다. 두 사람이 솔직해지는 장면을 기다리고 있어요.', DATE_SUB(v_now, INTERVAL 288 HOUR), DATE_SUB(v_now, INTERVAL 288 HOUR)),
    (811601, 81016, 81002, 5, '무너진 세상에서 책을 빌려준다는 설정이 좋네요. 거대한 전투보다 잃어버린 기억을 찾아주는 사건들이 오래 남습니다.', DATE_SUB(v_now, INTERVAL 72 HOUR), DATE_SUB(v_now, INTERVAL 72 HOUR)),
    (811602, 81016, 81003, 5, '새로운 도시를 만날 때마다 도서관의 의미도 조금씩 달라집니다. 서가와 지도 묘사가 좋아서 천천히 읽고 있어요.', DATE_SUB(v_now, INTERVAL 96 HOUR), DATE_SUB(v_now, INTERVAL 96 HOUR)),
    (811603, 81016, 81004, 5, NULL, DATE_SUB(v_now, INTERVAL 120 HOUR), DATE_SUB(v_now, INTERVAL 120 HOUR)),
    (811604, 81016, 81005, 5, NULL, DATE_SUB(v_now, INTERVAL 144 HOUR), DATE_SUB(v_now, INTERVAL 144 HOUR)),
    (811605, 81016, 81006, 5, NULL, DATE_SUB(v_now, INTERVAL 168 HOUR), DATE_SUB(v_now, INTERVAL 168 HOUR)),
    (811606, 81016, 81007, 5, NULL, DATE_SUB(v_now, INTERVAL 192 HOUR), DATE_SUB(v_now, INTERVAL 192 HOUR)),
    (811607, 81016, 81008, 5, NULL, DATE_SUB(v_now, INTERVAL 216 HOUR), DATE_SUB(v_now, INTERVAL 216 HOUR)),
    (811608, 81016, 81009, 5, NULL, DATE_SUB(v_now, INTERVAL 240 HOUR), DATE_SUB(v_now, INTERVAL 240 HOUR)),
    (811609, 81016, 81010, 5, NULL, DATE_SUB(v_now, INTERVAL 264 HOUR), DATE_SUB(v_now, INTERVAL 264 HOUR)),
    (811610, 81016, 81011, 4, '분위기는 정말 좋은데 여행 구간에서 진행이 느려지는 편입니다. 사건 사이에 쉬어가는 이야기라고 생각하고 읽으니 괜찮았어요.', DATE_SUB(v_now, INTERVAL 288 HOUR), DATE_SUB(v_now, INTERVAL 288 HOUR));
INSERT INTO review_comment (id, review_id, member_id, content, created_at, updated_at) VALUES
    (81001, 810101, 81001, '저도 규칙이 하나씩 바뀌는 부분이 더 무서웠어요. 그래서 인계장을 다시 읽어봤습니다.', DATE_SUB(v_now, INTERVAL 28 HOUR), DATE_SUB(v_now, INTERVAL 28 HOUR)),
    (81002, 810101, 81003, '기록실에서 잠깐 쉬는 장면이 있어서 다음 사건이 더 긴장되는 것 같아요.', DATE_SUB(v_now, INTERVAL 26 HOUR), DATE_SUB(v_now, INTERVAL 26 HOUR)),
    (81003, 810201, 81001, '자기 전에 한 장씩 읽는 방법 좋네요. 저는 질문만 메모해두고 주말에 다시 적어봤어요.', DATE_SUB(v_now, INTERVAL 49 HOUR), DATE_SUB(v_now, INTERVAL 49 HOUR)),
    (81004, 810401, 81005, '관측 캘린더 유용하더라고요. 날씨 좋은 날에 목성부터 찾아보려고 합니다.', DATE_SUB(v_now, INTERVAL 32 HOUR), DATE_SUB(v_now, INTERVAL 32 HOUR));
INSERT INTO book_stat_daily (id, book_id, stat_date, view_count)
INSERT INTO wiki_entry (id, book_id, reveal_chapter_id, type, subtype, name, tagline, summary, body) VALUES
    (81001, 81001, 81001001, 'CHARACTER', '인물', '윤서', '괴이청 신입 기록관', '괴이청 야간기록실에 발령받은 신입 기록관입니다.', '전임자의 인계장을 따라 사건을 기록합니다. 자신의 이름이 적힌 과거 기록을 발견하면서 기록실과 폐역의 관계를 조사합니다.'),
    (81002, 81001, 81001001, 'WORLD', '기관', '괴이청', '기록되지 않은 사건을 보관하는 기관', '일상에서 지워진 사건을 수집하고 보관하는 기관입니다.', '야간기록실은 사람들이 잠든 동안 발생하는 사건을 맡습니다. 기록관은 인계받은 권한 범위 안에서 문서를 열람합니다.'),
    (81003, 81001, 81001002, 'WORLD', '장소', '폐역 서고', '야간문으로 이어지는 보관실', '운행이 끊긴 역 아래에 남겨진 기록 보관실입니다.', '막차가 떠난 뒤에만 입구를 찾을 수 있습니다. 윤서는 야간기록부의 직인을 이용해 이곳에 들어갑니다.'),
    (81004, 81001, 81001001, 'ITEM', '도구', '야간기록부', '야간 근무의 인계 기록', '기록관의 인계와 열람 내역이 남는 장부입니다.', '직인이 찍힌 페이지에는 기록관의 권한이 담깁니다. 기록을 고치면 원래 내용을 지울 수 없고 수정한 흔적이 남습니다.'),
    (81005, 81001, 81001002, 'CONCEPT', '직인', '야록인', '기록관의 열람 권한', '괴이청 기록관의 권한을 인증하는 직인입니다.', '야간기록부에 찍힌 직인으로, 인증된 기록관에게 폐역 서고의 문을 여는 권한을 부여합니다.'),
    (81006, 81001, 81001002, 'CONCEPT', '통로', '야간문', '서로 떨어진 기록 공간을 잇는 문', '야록인에 인증된 기록관에게만 보이는 통로입니다.', '폐역 서고와 기록보관실을 잇습니다. 인증되지 않은 사람에게는 평범한 벽으로 보이며 두 장소 사이의 거리를 건너뜁니다.'),
    (81007, 81001, 81001002, 'CONCEPT', '현상', '잔록', '기록에 남은 기억의 흔적', '야록인을 사용한 뒤 잠깐 나타나는 기억의 흔적입니다.', '손을 댄 편지나 기록의 기억 일부가 짧은 장면으로 나타납니다. 같은 기록이라도 열람 시점에 따라 드러나는 장면이 다릅니다.'),
    (81008, 81001, 81001006, 'CHARACTER', '인물', '도경', '실종된 전임 기록관', '윤서가 인계받기 전에 야간기록실을 맡았던 기록관입니다.', '마지막 근무일지를 남긴 뒤 실종됐습니다. 일지에는 폐역으로 향한 시각만 적혀 있고 복귀 기록은 남아 있지 않습니다.');
