-- 로컬 시연 자료입니다. MySQL 8.4 / Flyway V1~V6 이상 적용 후 실행합니다.
-- 저장소 루트에서 node tools/db-seed.mjs seed로 적용하고 unseed로 제거합니다.
-- 기준: 시안 r3-kit.mjs의 작품 16종·표지·평점·서재 진행률과 R25 커뮤니티 문구,
--       server/mock/fixtures/works.json의 소개·목차, docs/테이블 정의서.md입니다.
-- 생성한 후속 회차 제목·회원 활동은 시연 데이터이며 실제 출판물/사용자 기록이 아닙니다.
--
-- 실행 계정에는 DML과 CREATE ROUTINE, ALTER ROUTINE, EXECUTE 권한이 필요합니다.
--
-- 보존: 기존 행을 삭제/갱신하지 않습니다. 같은 slug/닉네임/예약 ID와 충돌하면 전부 롤백합니다.
--       이미 이 파일로 생성한 북이 계정이 있으면 재삽입하지 않습니다(초기화 기능이 아닙니다).
--       ID 81001~81030과 810010~819017, 81001001~81016156 범위의 시드 ID를 예약합니다.
--       관리자 API의 @Positive 제약에 맞춰 양수 ID를 사용하므로 AUTO_INCREMENT 다음 값도 증가합니다.
--       실패/롤백 때도 MySQL의 AUTO_INCREMENT 순번은 되돌아가지 않습니다.
--       장르·카테고리·V6의 고정 게시판/스티커는 이름/코드로 재사용합니다.
--       검증 실패 시 프로시저가 ROLLBACK 후 원래 오류를 다시 반환합니다.
--
-- 이미지: ''는 API 서버 기준 /media/...입니다. 첫 적용 전에 끝 / 없는 이미지 서버 주소를 넣을 수 있습니다.
--         예: http://192.168.0.10:8090 (server/mock/index.mjs를 해당 호스트에서 실행한 경우입니다.)
--         파일은 server/src/main/resources/static/media/에 있습니다. SQL 실행만으로 정적 파일 제공이 시작되지는 않습니다.
SET @mobtwig_asset_origin = '';
--
-- 화면 범위: 홈/상세의 필수 필드, 16종 서재, 즐겨찾기 4개, 독서 기록 8개,
--            리뷰 160개(별점만 112개 포함), 작품별/주제별/홍보 글을 연결합니다.
-- 로그인: 아래 30명은 활동 표시용 계정이며 비밀번호는 로그인 불가 값입니다.
--         실제 로그인 검증에는 별도로 생성한 로그인 가능 계정을 사용합니다.
-- 본문: chapter.content_url은 NULL입니다. 회차 메타데이터/표시용 문자 수만 생성합니다.
--       실제 EPUB/본문 파일과 그 문자 위치 일치는 별도로 구현해야 합니다.
--       구매/결제/관계도 연결선/프로필 이미지/리뷰 공감은 V1~V6에 저장할 테이블이 없어 생성하지 않습니다.
--       홈 섹션 배치는 server/sdui/home.json의 영역으로 이 SQL이 수정하지 않습니다.
--       추천 수는 시안 표시용 누적 숫자입니다. 정의서의 '추천 기능 보류/0' 정책과 구분합니다.
--       스티커는 V6의 고정 4종을 사용하며 /stickers/emote-*.svg 파일 제공은 별도입니다.

SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
SET @mobtwig_previous_time_zone = @@session.time_zone;
SET time_zone = '+00:00';
DROP PROCEDURE IF EXISTS seed_mobtwig_design_demo_20261106;
DELIMITER $$
CREATE PROCEDURE seed_mobtwig_design_demo_20261106()
seed: BEGIN
    DECLARE v_now TIMESTAMP DEFAULT UTC_TIMESTAMP();
    DECLARE v_today DATE DEFAULT DATE(DATE_ADD(UTC_TIMESTAMP(), INTERVAL 9 HOUR));
    DECLARE v_reading_board BIGINT;
    DECLARE v_writing_board BIGINT;
    DECLARE v_promotion_board BIGINT;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;
    IF EXISTS (SELECT 1 FROM member WHERE id = 81001 AND email = 'design.booki@mobtwig.test') THEN
        COMMIT;
        SELECT '이미 적용된 시안 데이터입니다. 기존 활동을 유지했습니다.' AS result;
        LEAVE seed;
    END IF;

    SELECT MIN(id) INTO v_reading_board FROM board WHERE type = 'TOPIC' AND name = '독서 이야기';
    SELECT MIN(id) INTO v_writing_board FROM board WHERE type = 'TOPIC' AND name = '창작 이야기';
    SELECT MIN(id) INTO v_promotion_board FROM board WHERE type = 'PROMOTION' AND name = '작품 홍보';
    IF v_reading_board IS NULL OR v_writing_board IS NULL OR v_promotion_board IS NULL
       OR (SELECT COUNT(*) FROM sticker WHERE code IN ('WAVE','CHEER','THINK','THANKS')) <> 4 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'V6 고정 게시판/스티커를 먼저 적용하십시오.';
    END IF;

-- 1. 활동 회원과 읽기 설정입니다. 북이의 ID는 81001입니다.


-- 2. 공용 분류는 이름으로 재사용하며 웹소설에는 genre, 도서/매거진에는 category를 연결합니다.


-- 3. 도서 6종, 매거진 5종, 웹소설 5종입니다. 북이의 내 작품은 퇴근 후 던전 관리인 1종입니다.



-- 4. 웹소설은 시안의 실제 표시 개수(14/86/128/96/156화)만큼 생성합니다. 총 536개 목차/회차입니다.
-- 연재 시작일 이전의 회차는 첫날 일괄 등록분으로 처리하며 이후 회차는 하루 간격입니다.

-- 5. 내 서재/즐겨찾기/찜/진행률/최근 본 작품입니다. status는 현 스키마 제약용이며 화면에 예전 상태 탭을 추가하는 의미가 아닙니다.






-- 6. 작품마다 10명의 독립 별점과 3개의 본문 리뷰입니다. 평점 캐시는 실제 행에서 계산합니다.


UPDATE book b SET
    average_rating = (SELECT ROUND(AVG(r.rating), 2) FROM review r WHERE r.book_id = b.id AND r.deleted_at IS NULL),
    review_count = (SELECT COUNT(*) FROM review r WHERE r.book_id = b.id AND r.deleted_at IS NULL),
    wishlist_count = (SELECT COUNT(*) FROM wishlist w WHERE w.book_id = b.id)
WHERE b.id BETWEEN 81001 AND 81016;

-- 7. 최근 7일의 조회 수입니다. 누적 조회 수의 일부만 최근 통계에 배분합니다. stat_date는 KST 기준입니다.
WITH RECURSIVE days(n) AS (SELECT 0 UNION ALL SELECT n + 1 FROM days WHERE n < 6)
SELECT 810000 + (b.id - 81000) * 10 + d.n, b.id,
       DATE_SUB(v_today, INTERVAL d.n DAY), FLOOR(b.view_count * (0.018 + 0.002 * d.n))
FROM book b CROSS JOIN days d WHERE b.id BETWEEN 81001 AND 81016;

-- 8. 세계관입니다. 고유 용어와 인물/장소를 구분하고 후반 공개 항목은 별도 회차에 연결합니다.



-- 9. 작품별 게시판 16개입니다. 주제별 글에는 작품을 연결하지 않으며 홍보 글만 내 작품을 연결합니다.

그냥 피곤하다고 쓰던 날도 이유를 나눠 적으니 조금 다르게 보이네요.
다른 분들은 책에 나온 질문 중 어떤 걸 적어보셨나요?', NULL, 'PUBLISHED', DATE_SUB(v_now, INTERVAL 9 HOUR), DATE_SUB(v_now, INTERVAL 9 HOUR), DATE_SUB(v_now, INTERVAL 9 HOUR)),
    (81002, 81004, 81004, 81005, 'IMPRESSION', '이번 호는 관측 기사부터 읽었어요', '밤하늘에서 목성을 찾는 기사를 먼저 읽었습니다.
사진 옆에 관측할 때 볼 지점이 정리돼 있어서 따라가기 편했어요.
망원경 없이 읽으시는 분들은 어느 기사가 가장 재미있으셨나요?', NULL, 'PUBLISHED', DATE_SUB(v_now, INTERVAL 8 HOUR), DATE_SUB(v_now, INTERVAL 8 HOUR), DATE_SUB(v_now, INTERVAL 8 HOUR)),
    (81003, 81001, 81001, 81006, 'IMPRESSION', '기록관 분위기 때문에 계속 읽게 돼요', '무서운 장면보다 기록관에서 일하는 장면이 더 오래 기억에 남아요.

한 사건이 끝나면 잠깐 숨을 돌릴 시간이 있어서 다음 화도 자연스럽게 읽게 됩니다. 밤에 불 하나 켜놓고 읽으면 분위기가 잘 맞아요.

아직 초반인데, 저처럼 배경 묘사 때문에 읽고 계신 분도 있나요?', NULL, 'PUBLISHED', DATE_SUB(v_now, INTERVAL 7 HOUR), DATE_SUB(v_now, INTERVAL 7 HOUR), DATE_SUB(v_now, INTERVAL 7 HOUR)),
    (81004, v_reading_board, NULL, 81007, 'QUESTION', '출퇴근길에는 얼마나 읽으세요?', '출근길이 편도 30분인데 휴대폰만 보다가 내릴 때가 많아요.
한 권 완독을 목표로 잡으니 부담돼서 이번 주부터 시간을 정해서 읽어보려고 합니다.
시간과 분량 중에 어떤 기준이 습관을 들이기 좋았나요?', NULL, 'PUBLISHED', DATE_SUB(v_now, INTERVAL 6 HOUR), DATE_SUB(v_now, INTERVAL 6 HOUR), DATE_SUB(v_now, INTERVAL 6 HOUR)),
    (81005, v_reading_board, NULL, 81009, 'QUESTION', '메모는 종이에 하세요, 앱에 하세요?', '종이에 쓰면 기억은 잘 나는데 나중에 찾기가 어렵고, 앱은 모아두기만 하게 됩니다.
읽다가 멈추는 시간이 길어지지 않게 짧게 남기고 싶은데 다들 어떻게 하고 계신가요?', NULL, 'PUBLISHED', DATE_SUB(v_now, INTERVAL 5 HOUR), DATE_SUB(v_now, INTERVAL 5 HOUR), DATE_SUB(v_now, INTERVAL 5 HOUR)),
    (81006, v_promotion_board, 81014, 81001, 'PROMOTION', '퇴근하고 던전을 돌보는 이야기입니다.', '퇴근 후엔 또 다른 일이 시작됩니다. 첫 작품을 연재 중인 북이입니다.

퇴근길에 던전 관리 계약을 맡은 회사원의 이야기입니다. 몬스터와 싸우는 대신 시설을 고치고 입주자 민원을 받습니다.
가볍게 읽을 수 있는 생활 판타지를 쓰고 있습니다. 읽어주셔서 감사합니다.', NULL, 'PUBLISHED', DATE_SUB(v_now, INTERVAL 4 HOUR), DATE_SUB(v_now, INTERVAL 4 HOUR), DATE_SUB(v_now, INTERVAL 4 HOUR)),
    (81007, v_writing_board, NULL, 81012, 'STORY', '퇴고할 때 소리 내어 읽어봤습니다', '문장이 자꾸 길어져서 오늘은 한 회차를 소리 내어 읽어봤습니다.
숨이 차는 부분에서 문장을 나누니 설명도 덜 겹치더라고요. 대화문을 고칠 때 특히 도움이 됐습니다.', NULL, 'PUBLISHED', DATE_SUB(v_now, INTERVAL 3 HOUR), DATE_SUB(v_now, INTERVAL 3 HOUR), DATE_SUB(v_now, INTERVAL 3 HOUR)),
    (81008, 81001, 81001, 81010, 'THEORY', '두 번째 직인은 전임자와 관련 있을까요?', '5화에서 발견한 문양이 첫 인계장에 남은 흔적과 같아 보여요.
단순한 통행 권한이 아니라 기록을 넘기는 표시일 수도 있겠다는 생각이 들었습니다.
아직 뒤 회차는 안 읽었으니 5화까지 내용으로만 이야기하고 싶어요.', 81001005, 'PUBLISHED', DATE_SUB(v_now, INTERVAL 2 HOUR), DATE_SUB(v_now, INTERVAL 2 HOUR), DATE_SUB(v_now, INTERVAL 2 HOUR));



SELECT 81001, 81007, 1, id FROM sticker WHERE code = 'CHEER';
SELECT 81001, 81001, 1, id FROM sticker WHERE code = 'THANKS';
SELECT 81002, 81014, 1, id FROM sticker WHERE code = 'THINK';


-- 10. 화면 표시와 데이터 개수의 최소 일관성 검사입니다. 불일치하면 앞의 모든 DML을 롤백합니다.
    IF (SELECT COUNT(*) FROM book WHERE id BETWEEN 81001 AND 81016 AND publish_status = 'PUBLISHED') <> 16
       OR (SELECT COUNT(*) FROM chapter WHERE book_id BETWEEN 81001 AND 81016) <> 536
       OR (SELECT COUNT(*) FROM review WHERE book_id BETWEEN 81001 AND 81016 AND deleted_at IS NULL) <> 160
       OR (SELECT COUNT(*) FROM library_book WHERE member_id = 81001 AND is_favorite) <> 4 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = '시안 데이터 개수 검증에 실패했습니다.';
    END IF;
    COMMIT;
    SELECT '시안 데이터 적용을 완료했습니다.' AS result, 81001 AS demo_member_id;
END$$
DELIMITER ;
CALL seed_mobtwig_design_demo_20261106();
DROP PROCEDURE seed_mobtwig_design_demo_20261106;
SET time_zone = @mobtwig_previous_time_zone;

-- 적용 결과 확인입니다.
SELECT content_type, COUNT(*) AS work_count FROM book
WHERE id BETWEEN 81001 AND 81016 GROUP BY content_type;
SELECT b.slug, b.title, b.average_rating, b.review_count, b.view_count, b.recommend_count,
       b.wishlist_count, COUNT(c.id) AS chapter_count
FROM book b LEFT JOIN chapter c ON c.book_id = b.id
WHERE b.id BETWEEN 81001 AND 81016 GROUP BY b.id ORDER BY b.id ASC;
SELECT p.id, p.title,
       (SELECT COUNT(*) FROM post_comment c WHERE c.post_id = p.id) AS comments,
       (SELECT COUNT(*) FROM post_reaction r WHERE r.post_id = p.id) AS reactions
FROM post p WHERE p.id BETWEEN 81001 AND 81008 ORDER BY p.id ASC;
